"""SQLite store for app state. Derived data stays in tidy/*.csv; this holds what only
the user can produce - annotations, answers, ledger state - plus a cache of the tidy
tables so the web layer has one query surface."""
import sqlite3, os

from estebot import config

_cfg = config.load()


DB = str(_cfg.data_file("app.sqlite"))

SCHEMA = """
-- ---- cached projections of tidy/*.csv (regenerated by ingest, never hand-edited)
CREATE TABLE IF NOT EXISTS weight (
  date TEXT PRIMARY KEY, weight_lb REAL NOT NULL, source TEXT);
CREATE TABLE IF NOT EXISTS nutrition (
  date TEXT PRIMARY KEY, kcal REAL, protein_g REAL, carbs_g REAL, fat_g REAL,
  fiber_g REAL, sodium_mg REAL, meals_logged INT, complete INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS daily (
  date TEXT PRIMARY KEY, steps REAL, active_kcal REAL, exercise_min REAL,
  resting_hr REAL, hrv_sdnn REAL, resp_rate REAL, spo2 REAL, basal_kcal REAL);
CREATE TABLE IF NOT EXISTS sleep (
  night TEXT PRIMARY KEY, asleep_hr REAL, deep_hr REAL, rem_hr REAL,
  efficiency_pct REAL, n_wakes REAL);
CREATE TABLE IF NOT EXISTS lift_session (
  date TEXT PRIMARY KEY, n_exercises INT, n_sets INT, total_volume_lb REAL,
  top_set_lb REAL, muscle_groups TEXT, session_min REAL, hard_sets INT,
  mean_rpe REAL);
CREATE TABLE IF NOT EXISTS e1rm (
  exercise TEXT, muscle_group TEXT, date TEXT, best_e1rm_lb REAL,
  best_set_weight_lb REAL, best_set_reps INT, PRIMARY KEY (exercise, date));
-- Every logged set, for the training plan: the next target needs each set's reps and RPE,
-- which e1rm (one best set per exercise and day) does not keep. No key: Jefit-era rows
-- repeat (date, exercise, set_idx).
CREATE TABLE IF NOT EXISTS lift_set (
  date TEXT, exercise TEXT, set_idx INT, weight_lb REAL, reps INT, rpe REAL, set_type TEXT);
CREATE INDEX IF NOT EXISTS idx_lift_set ON lift_set(exercise, date);

-- ---- authored state (the part no sensor can produce)
CREATE TABLE IF NOT EXISTS workout (
  date TEXT, start TEXT, activity TEXT, duration_min REAL, PRIMARY KEY (date, start, activity));

CREATE TABLE IF NOT EXISTS nutrient (
  date TEXT, nutrient TEXT, amount REAL, kcal_coverage_pct REAL, PRIMARY KEY (date, nutrient));

-- Authored settings (the weight goal). Ingest never touches this table.
CREATE TABLE IF NOT EXISTS setting (key TEXT PRIMARY KEY, value TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS annotation (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  start_date TEXT NOT NULL, end_date TEXT,
  type TEXT, label TEXT, note TEXT,
  source TEXT NOT NULL,              -- which file it came from
  excused INT NOT NULL DEFAULT 0,    -- removes these days from coverage denominators
  UNIQUE (start_date, label, source));

-- Daily subjective check-in. The sensors cannot see any of this, and when the limiter is a
-- recurring lower-back problem it is likely the most predictive input there is.
CREATE TABLE IF NOT EXISTS checkin (
  date TEXT PRIMARY KEY,
  back TEXT NOT NULL DEFAULT 'ok',      -- ok | tired | sore | spasm
  soreness INT,                          -- 0-3 general
  energy INT,                            -- 0-3 systemic: how you feel overall
  -- Inter-set recovery is tracked separately from energy because they diverge. In one
  -- session heavy deadlifts and cleans needed long rests while bodyweight pull-ups
  -- felt strong enough to add a rep. One scalar cannot hold both; forcing it loses the
  -- signal that actually matters, which is how taxed the heavy work was.
  inter_set_recovery INT,                -- 0-3, 0 = needed much longer rests than usual
  note TEXT,
  source TEXT NOT NULL DEFAULT 'manual', -- manual | derived; a manual row is never overwritten
  needs_review INT NOT NULL DEFAULT 0,   -- 1 = derived from conflicting notes; ask, don't guess
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  back_reported INT NOT NULL DEFAULT 1,
  -- Tapped on the page. Notes say sick or injured in words, which unwell_days reads from
  -- the annotations; these are the same two facts for someone who never writes a note.
  sick INT NOT NULL DEFAULT 0,
  injured INT NOT NULL DEFAULT 0);

-- A check-in said in a sentence and read onto the tap card (web/checkin_text.py). Only a
-- draft: it prefills the card, and nothing counts until Save writes the checkin row.
CREATE TABLE IF NOT EXISTS checkin_draft (
  date TEXT PRIMARY KEY,
  back TEXT, energy INT, inter_set_recovery INT,
  sick INT NOT NULL DEFAULT 0, injured INT NOT NULL DEFAULT 0,
  note TEXT,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP);

CREATE INDEX IF NOT EXISTS idx_ann_start ON annotation(start_date);
"""

def connect(path=None):
    """A connection to one person's database; None means this process's config."""
    con = sqlite3.connect(path or DB)
    con.row_factory = sqlite3.Row
    con.execute("PRAGMA foreign_keys=ON")
    return con

# Columns added after a table first shipped. CREATE TABLE IF NOT EXISTS never alters an
# existing table, so without this an older database keeps its old shape forever. That's
# how checkin.source and needs_review came to exist in the original live database (added by
# hand) but not in the schema, which broke ingest and the check-in form on every fresh DB.
_ADDED_COLUMNS = {
    "lift_session": [("hard_sets", "INT"), ("mean_rpe", "REAL")],
    "daily": [("basal_kcal", "REAL")],
    "checkin": [
        ("inter_set_recovery", "INT"),
        ("source", "TEXT NOT NULL DEFAULT 'manual'"),
        ("needs_review", "INT NOT NULL DEFAULT 0"),
        # 1 when the back was actually reported. A note that never mentions it used to store
        # back='ok' (the column's default) and read as a green "back ok" (18 Oct 2026).
        # Manual check-ins always report it, hence the default.
        ("back_reported", "INT NOT NULL DEFAULT 1"),
        ("sick", "INT NOT NULL DEFAULT 0"),
        ("injured", "INT NOT NULL DEFAULT 0"),
    ],
}

def _migrate(con):
    for table, cols in _ADDED_COLUMNS.items():
        have = {r["name"] for r in con.execute(f"PRAGMA table_info({table})")}
        for name, decl in cols:
            if name not in have:
                con.execute(f"ALTER TABLE {table} ADD COLUMN {name} {decl}")

def init(path=None):
    con = connect(path)
    con.executescript(SCHEMA)
    _migrate(con)
    con.commit()
    return con

def get_setting(con, key, default=None):
    r = con.execute("SELECT value FROM setting WHERE key=?", (key,)).fetchone()
    return r["value"] if r else default

def set_setting(con, key, value):
    con.execute("INSERT INTO setting (key, value) VALUES (?, ?) "
                "ON CONFLICT(key) DO UPDATE SET value=excluded.value", (key, str(value)))
    con.commit()

if __name__ == "__main__":
    init(); print(f"initialised {DB}")
